// The Handbook book, generated by data/handbook_v4/build_handbook_v4.py (same chapters as the app; do not edit the JSON).
import book from "./handbook.json";
import type { Block } from "@/components/handbook-blocks";

export type Chapter = { slug: string; part: string; partTitle: string; title: string; summary: string; minutes: number; sources: Record<string, string>; blocks: Block[] };

export const chapters = book as unknown as Chapter[]; // checked by the builder (check_book), not by TypeScript
export const chapterBySlug = (slug: string) => chapters.find((c) => c.slug === slug);

export const HANDBOOK_NOTE =
  "General information from published guidelines, not medical advice, and not reviewed by a clinician. See a doctor for pain, illness, pregnancy or before hard training if you have a condition.";
